function containsCycle(grid) {
  const rows = grid.length;
  const cols = grid[0].length;
  const visited = Array.from({ length: rows }, () => new Array(cols).fill(false));
  const directions = [[1, 0], [-1, 0], [0, 1], [0, -1]];

  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      if (visited[r][c]) continue;
      visited[r][c] = true;
      const stack = [[r, c, -1, -1]];
      while (stack.length > 0) {
        const [row, col, fromRow, fromCol] = stack.pop();
        for (const [dr, dc] of directions) {
          const nextRow = row + dr;
          const nextCol = col + dc;
          if (nextRow < 0 || nextRow >= rows || nextCol < 0 || nextCol >= cols) continue;
          if (grid[nextRow][nextCol] !== grid[row][col]) continue;
          if (nextRow === fromRow && nextCol === fromCol) continue;
          if (visited[nextRow][nextCol]) return true;
          visited[nextRow][nextCol] = true;
          stack.push([nextRow, nextCol, row, col]);
        }
      }
    }
  }
  return false;
}

