function containsCycle(grid) {
  // A graph has a cycle exactly when it has more edges than (vertices - components).
  const m = grid.length, n = grid[0].length;
  const label = [];
  for (let i = 0; i < m * n; i++) label.push(i);
  const edges = [];
  for (let i = 0; i < m; i++)
    for (let j = 0; j < n; j++) {
      if (i + 1 < m && grid[i + 1][j] === grid[i][j]) edges.push([i * n + j, (i + 1) * n + j]);
      if (j + 1 < n && grid[i][j + 1] === grid[i][j]) edges.push([i * n + j, i * n + j + 1]);
    }
  let changed = true;
  while (changed) {
    changed = false;
    for (const [a, b] of edges) {
      const low = Math.min(label[a], label[b]);
      if (label[a] !== low || label[b] !== low) { label[a] = low; label[b] = low; changed = true; }
    }
  }
  const components = new Set(label).size;
  return edges.length > m * n - components;
}

