function generate(rand, size) {
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const pick = k => letters[Math.floor(rand() * k)];
  if (size !== 'large') {
    const m = 1 + Math.floor(rand() * 5), n = 1 + Math.floor(rand() * 5), k = 1 + Math.floor(rand() * 3);
    return [Array.from({ length: m }, () => Array.from({ length: n }, () => pick(k)))];
  }
  const m = 50 + Math.floor(rand() * 51), n = 50 + Math.floor(rand() * 51);
  const mode = rand();
  if (mode < 0.34) {
    const k = 2 + Math.floor(rand() * 25);
    return [Array.from({ length: m }, () => Array.from({ length: n }, () => pick(k)))];
  }
  // A comb of 'a' (column 0 plus every even row) with other letters between the teeth has no cycle.
  const grid = Array.from({ length: m }, (_, i) => Array.from({ length: n }, (_, j) => (j === 0 || i % 2 === 0 ? 'a' : letters[1 + Math.floor(rand() * 4)])));
  if (mode >= 0.67 && m >= 3) {
    // One extra 'a' between two teeth closes exactly one loop through column 0.
    const row = 1 + 2 * Math.floor(rand() * Math.floor((m - 1) / 2));
    grid[row][1 + Math.floor(rand() * (n - 1))] = 'a';
  }
  return [grid];
}
